// This script is loaded both on the frontend page and in the Visual Builder.
jQuery( function($) {
	$('.el_ajax_search_field').on( 'input', function(e) {
		let $this                = $( this ),
			$pagination          = $this.closest('.el_ajax_search').find('.el_ajax_search_pagination_wrap ul'),
			$allResultText       = $this.closest('.el_ajax_search').find('.el_ajax_search_pagination_wrap .el_ajax_search_total_result'),
			value                = $this.val(),
			searchPostType       = $this.data('search-post-type'),
			searchIn             = $this.data('search-in'),
			displayFields        = $this.data('display-fields'),
			urlNewWindow         = $this.data('url-new-window'),
			numberOfResults      = $this.data('number-of-results'),
			noResultText         = $this.data('no-result-text'),
			orderBy              = $this.data('orderby'),
			order                = $this.data('order'),
			excludePostTypes     = $this.data('exclude-post-types'),
			excludePostIds       = $this.data('exclude-post-ids'),
			excludeTaxonomies    = $this.data('exclude-taxonomies'),
			includeTaxonomies    = $this.data('include-taxonomies'),
			masonry              = $this.data('use-masonry'),
			excerpt_length       = $this.data('excerpt-length'),
			result_layout        = $this.data('result-layout'),
			show_post_type_label = $this.data('show_post_type_label'),
			exclude_protected    = $this.data('exclude_protected_posts'),
			page                 = $pagination.data('current-page');

		if ( ! value || '' === value ) {
			$this.closest('.el_ajax_search').removeClass('el_ajax_search_active');
			$this.closest('.el_ajax_search').parents('.et_pb_column').removeClass('el_ajax_search_active_parent');
			$this.closest('.el_ajax_search').parents('.et_pb_row').removeClass('el_ajax_search_active_parent');
			$this.parents('.el_ajax_search_field_wrap').removeClass('el_ajax_search_loader');

			if ( $pagination.length > 0 ) {
				if ( $pagination.hasClass( 'pagination-initiated' ) ) {
					$pagination.twbsPagination( 'destroy' );
					$pagination.removeClass( 'pagination-initiated' );
				}
				$pagination.hide();
			}
			if ( $allResultText.length > 0 ) {
				$allResultText.hide();
			}
			return false;
		}

		if ( el_divi_ajax_search_validate_script( value ) && el_divi_ajax_search_validate_html( value ) && value.length > 2 ) {
			if ( ! $this.parents('.el_ajax_search_field_wrap').hasClass('el_ajax_search_loader') ) {
				$this.parents('.el_ajax_search_field_wrap').addClass('el_ajax_search_loader');
			}

			let ajaxSearchNonce = $this.closest('.el_ajax_search').find('.el_divi_ajax_search_nonce').val();
			if ( ! el_divi_ajax_search_validate_script( ajaxSearchNonce ) || ! el_divi_ajax_search_validate_html( ajaxSearchNonce ) ) {
				return false;
			}

			$.ajax( {
				type: 'POST',  
				url: DiviAjaxSearchFrontendData.ajaxurl,
				data: {
					action: 'el_ajax_search_results', 
					divi_ajax_search_nonce: ajaxSearchNonce,
					post_types: searchPostType,
					search_in: searchIn,
					display_fields: displayFields,
					url_new_window: urlNewWindow,
					number_of_results: numberOfResults,
					no_result_text: noResultText,
					orderby: orderBy,
					order: order,
					masonry: masonry,
					exclude_post_types: excludePostTypes,
					exclude_post_ids: excludePostIds,
					exclude_taxonomies: excludeTaxonomies,
					include_taxonomies: includeTaxonomies,
					search: value,
					excerpt_length: excerpt_length,
					result_layout: result_layout,
					pagination_enabled: ( $pagination.length > 0 ) ? 'on' : 'off',
					page: page,
					show_post_type_label: show_post_type_label,
					exclude_protected: exclude_protected
				},
				success: function(response) {
					$this.parents('.el_ajax_search_field_wrap').removeClass('el_ajax_search_loader');
					if ( '' !== response.html ) {
						$this.closest('.el_ajax_search').addClass('el_ajax_search_active');
						$this.closest('.el_ajax_search').parents('.et_pb_column').addClass('el_ajax_search_active_parent');
						$this.closest('.el_ajax_search').parents('.et_pb_row').addClass('el_ajax_search_active_parent');
						
						$this.closest('.el_ajax_search').find('.el_ajax_search_results_wrap .el_ajax_search_results').remove();
						$this.closest('.el_ajax_search').find('.el_ajax_search_results_wrap .el_ajax_search_no_results').remove();
						$this.closest('.el_ajax_search').find('.el_ajax_search_results_wrap').prepend( response.html );

						$this.closest('.el_ajax_search').find('.el_ajax_search_results_wrap .el_ajax_search_result_link_wrap').hide();
						if ( $this.closest('.el_ajax_search').find('.el_ajax_search_results_wrap .el_ajax_search_results').length > 0 ) {
							$this.closest('.el_ajax_search').find('.el_ajax_search_results_wrap .el_ajax_search_result_link_wrap').show();
						}

						// Check for pagination.
						if ( $pagination.length > 0 ) {
							let total_pages = ( response.total_pages || 0 === response.total_pages ) ? response.total_pages : -1;
							if ( total_pages > 1 && page === 1 ) {

								// Hide first.
								$pagination.hide();

								let $options = {
									paginationClass: 'el_ajax_search_pagination',
									hideOnlyOnePage: true,
									totalPages: ( response.total_pages ) ? response.total_pages : 0,
									visiblePages: 5,
									startPage: 1,
									initiateStartPageClick: false,
									first: false,
									last: false,
									prev: false,
									next: false,
									onPageClick: function (event, page) {
										$pagination.data( 'current-page', page );
										$this.trigger( 'input' );
									}
								};

								if ( 'on' === $pagination.data('show_prev_next')  ) {
									$options.prev = $pagination.data('prev_text');
									$options.next = $pagination.data('next_text');
								}
								
								if ( $pagination.hasClass( 'pagination-initiated' ) ) {
									$pagination.twbsPagination( 'destroy' );
									$pagination.removeClass( 'pagination-initiated' );
								}
								$pagination.twbsPagination( $options ).addClass( 'pagination-initiated' ).show();
							} else if ( total_pages !== -1 && page === 1 ) {
								$pagination.twbsPagination( 'destroy' );
								$pagination.removeClass( 'pagination-initiated' ).hide();
							} else if ( page > 1 ) {
								$pagination.show();
							}
						}

						// Check for all result text.
						if ( $allResultText.length > 0 ) {
							$allResultText.hide();
							$allResultText.find( '.el-ajax-str-range' ).html( '' );
							$allResultText.find( '.el-ajax-str-total' ).html( '' );

							let total_posts = parseInt( $allResultText.attr( 'data-total_posts' ) );
							if ( 1 === page && 'undefined' !== typeof (response.total_posts) && '' !== response.total_posts ) {
								total_posts = parseInt( response.total_posts );
								$allResultText.attr( 'data-total_posts', total_posts );
							}
							if ( total_posts > 0 ) {
								$startPage = parseInt( numberOfResults ) * ( parseInt( page ) - 1 ) + 1;
								$lastPage  = parseInt( numberOfResults ) * parseInt( page );
								$lastPage  = ( $lastPage < total_posts ) ? $lastPage : total_posts;

								$allResultText.find( '.el-ajax-str-range' ).html( $startPage + ' - ' + $lastPage );
								$allResultText.find( '.el-ajax-str-total' ).html( total_posts );
								$allResultText.show();
							}
						}
						
						// Check for isotope.
						if ( $this.closest('.el_ajax_search').find('.el_ajax_search_result_masonry').length > 0 ) {
							$this.closest('.el_ajax_search').find('.el_ajax_search_result_masonry .el_ajax_search_items').isotope( {
								// options.
								itemSelector: '.el_ajax_search_isotope_item',
								layoutMode: 'masonry',
								percentPosition: true,
								resize: true,
								masonry: {
									columnWidth: '.el_ajax_search_isotope_item',
									gutter: '.el_ajax_search_isotope_item_gutter'
								}
							} );
						}
					} else {
						$this.closest('.el_ajax_search').removeClass('el_ajax_search_active');
						$this.closest('.el_ajax_search').parents('.et_pb_column').removeClass('el_ajax_search_active_parent');
						$this.closest('.el_ajax_search').parents('.et_pb_row').removeClass('el_ajax_search_active_parent');
						if ( $pagination.hasClass( 'pagination-initiated' ) ) {
							$pagination.twbsPagination( 'destroy' );
							$pagination.removeClass( 'pagination-initiated' ).hide();
						}
						if ( $allResultText.length > 0 ) {
							$allResultText.hide();
						}
					}
				},
				error: function() {
				}
			} );
		} else {
			$this.parents('.el_ajax_search_field_wrap').removeClass('el_ajax_search_loader');
			$this.closest('.el_ajax_search').removeClass('el_ajax_search_active');
			$this.closest('.el_ajax_search').parents('.et_pb_column').removeClass('el_ajax_search_active_parent');
			$this.closest('.el_ajax_search').parents('.et_pb_row').removeClass('el_ajax_search_active_parent');
			el_divi_ajax_search_close_all_lists($this);

			if ( $pagination.length > 0 ) {
				if ( $pagination.hasClass( 'pagination-initiated' ) ) {
					$pagination.twbsPagination( 'destroy' );
					$pagination.removeClass( 'pagination-initiated' );
				}
				$pagination.hide();
			}
			if ( $allResultText.length > 0 ) {
				$allResultText.hide();
			}
		}
	} );

	$( '.el_ajax_search_field' ).on( 'keyup', function() {
		let $this = $(this),
			value = $this.val();

		// Reset the pagination.
		$this.closest('.el_ajax_search').find( '.el_ajax_search_pagination_wrap .el_ajax_search_pagination' ).data( 'current-page', 1 );

		if ( '' === value ) {
			$this.closest('.el_ajax_search').removeClass('el_ajax_search_active');
			$this.closest('.el_ajax_search').parents('.et_pb_column').removeClass('el_ajax_search_active_parent');
			$this.closest('.el_ajax_search').parents('.et_pb_row').removeClass('el_ajax_search_active_parent');
			$this.parent().removeClass('el_has_text');
			el_divi_ajax_search_close_all_lists($this);
		} else {
			$this.parent().addClass('el_has_text');
		}

		// Hide link by default.
		$this.closest('.el_ajax_search').find( '.el_ajax_search_result_link_wrap' ).hide();

		// Set the URL params.
		if ( $this.closest('.el_ajax_search').find( '.el_ajax_search_result_link' ).length > 0 ) {
			let current_url = $this.closest('.el_ajax_search').find( '.el_ajax_search_result_link' ).attr( 'href' );
			if ( '' !== current_url ) {
				var url = new URL( current_url );
				url.searchParams.set( 's', value );
				$this.closest('.el_ajax_search').find( '.el_ajax_search_result_link' ).attr( 'href', url.href );
			}
		}
	} );

	$( '.el_ajax_search_field' ).on( 'focus', function() {
		$('.el_ajax_search_field').not($(this)).closest('.el_ajax_search').removeClass('el_ajax_search_active');
		$('.el_ajax_search_field').not($(this)).closest('.el_ajax_search').parents('.et_pb_column').removeClass('el_ajax_search_active_parent');
		$('.el_ajax_search_field').not($(this)).closest('.el_ajax_search').parents('.et_pb_row').removeClass('el_ajax_search_active_parent');

		$(this).closest('.el_ajax_search').find('.el_ajax_search_results_wrap .el_ajax_search_result_link_wrap').hide();
		if ( $(this).closest('.el_ajax_search').find('.el_ajax_search_results_wrap .el_ajax_search_results').length > 0 ) {
			$(this).closest('.el_ajax_search').find('.el_ajax_search_results_wrap .el_ajax_search_result_link_wrap').show();
		}
	} );

	$( '.el_ajax_search_field' ).on( 'click', function (e) {
		$( this ).trigger( 'input' );
	} );

	// Clear button clicked.
	$( '.el_ajax_search' ).on( 'click', '.el_ajax_clear_icon', function(e) {
		$( this ).parent().parent().removeClass( 'el_has_text' );
		$( this ).parent().parent().find( '.el_ajax_search_field' ).val( '' ).trigger( 'input' );
		$( this ).parents( '.el_ajax_search_wrap' ).find('.el_ajax_search_results_wrap .el_ajax_search_no_results').remove();
	} );
	
	$( 'html, body' ).on( 'click', function (e) {
		el_divi_ajax_search_close_all_lists(e.target);
	} );

	$( '.el_ajax_search' ).on( 'click', '.el-icon-click-show-searchbar .el_ajax_search_icon', function() {
		$( this ).parents( '.el-icon-click-show-searchbar' ).toggleClass( 'el-icon-show-searchbar' );
	} );

	// Update data-quantity.
	$( '.el_ajax_search' ).on( 'click input', 'input.qty', function() {
		$(this).parent().parent().find( 'a.ajax_add_to_cart' ).attr( 'data-quantity', $(this).val() );
		$( '.added_to_cart' ).remove(); // Optional: Removing other previous "view cart" buttons.
	} ).on( 'click', '.add_to_cart_button', function() {
		var button = $(this);
		setTimeout( function(){
			button.parent().find( '.quantity > input.qty' ).val(1); // reset quantity to 1.
		}, 1000 ); // After 1 second.
	} );
} );

/* close all lists in the document, except the one passed as an argument */
function el_divi_ajax_search_close_all_lists(element) {
	jQuery('.el_ajax_search_results').each( function() {
		let $this = jQuery(this);
		if ( ! $this.is( element ) && ! $this.is( jQuery( element ).parents( $this ) ) && jQuery(element).parents('.el_ajax_search_active').length < 1 ) {
			jQuery(this).next('.el_ajax_search_result_link_wrap').hide();
			jQuery(this).parent().prev('.el_ajax_search_pagination_wrap').find('ul').hide();
			jQuery(this).parent().prev('.el_ajax_search_pagination_wrap').find('.el_ajax_search_total_result').hide();
			jQuery(this).remove();
		}
	} );

	jQuery('.el_ajax_search_results_wrap').each( function(element) {
		let $this = jQuery( this );
		if ( ! $this.is( element ) && ! $this.is( jQuery( element ).parents( $this ) ) && jQuery(element).parents('.el_ajax_search_active').length < 1 ) {
			$this.find( '.el_ajax_search_no_results' ).remove();
		}
	} );
}

/* Script Vadlidation */
function el_divi_ajax_search_validate_script(pass) {
	var filter =  /<script>/i;
	if ( filter.test(pass) ) {
		return false;   
	} else {
		return true;
	}
}

/* HTML Vadlidation */
function el_divi_ajax_search_validate_html(pass) {
	var filter =  /</;
	if ( filter.test(pass) ) {
		return false;   
	} else {
		return true;
	}
}
